using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Runtime.InteropServices;
using GTA;
using GTA.Math;
using GTA.Native;

// Shared inventory (other scripts in the same DLL can use it)
public static class Inv
{
    public const int Bandage = 0;
    public const int Armor = 1;
    public const int Medkit = 2;
    public const int Water = 3;
    public const int Burger = 4;
    public const int Energy = 5;
    public const int Revive = 6;

    public static int[] Qty = new int[7];
    public static bool Dirty;
    public static bool WantBandage;
    public static bool WantArmor;
    public static bool WantRevive;
    public static bool Busy;      // carrying / reviving someone

    public static bool Take(int id)
    {
        if (id < 0 || id >= Qty.Length) return false;
        if (Qty[id] <= 0) return false;
        Qty[id]--;
        Dirty = true;
        return true;
    }
}

public class ItemSystem : Script
{
    // ===== Keys =====
    int BagKey = 0x49;        // I
    int ShopKey = 0x45;       // E (near a shop)
    int AnywhereKey = 0x4F;   // O (only if ShopAnywhere = true)
    int KUp = 0x26, KDown = 0x28, KLeft = 0x25, KRight = 0x27;
    int KEnter = 0x0D, KBack = 0x08;
    int KTab = 0x09;          // next category
    int KBuySell = 0x54;      // T  buy / sell
    int KQty = 0x51;          // Q  quantity 1 / 5 / 10

    // true = open the shop from anywhere with the O key
    const bool ShopAnywhere = false;
    // ================

    static readonly string[] Names = {
        "Bandage", "Body Armor", "Medkit",
        "Water", "Burger", "Energy Drink", "Revive Kit"
    };
    static readonly int[] Cat = { 1, 2, 1, 3, 3, 3, 1 };
    static readonly string[] CatNames = {
        "ALL", "MEDICAL", "ARMOR", "FOOD"
    };
    static readonly int[] BuyPrice = { 150, 500, 300, 20, 40, 60, 1000 };
    static readonly int[] SellPrice = { 50, 150, 100, 5, 10, 20, 300 };
    static readonly int[] QtyOptions = { 1, 5, 10 };

    // icon files (written to scripts\ItemIcons on first run)
    static readonly string[] IconFiles = {
        "bandage", "armor", "medkit", "water",
        "burger", "energy", "revive"
    };
    static readonly string[] IconB64 = {
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    };

    static readonly Vector3[] Shops = {
        new Vector3(-48.5f, -1757.5f, 29.4f),
        new Vector3(25.7f, -1347.3f, 29.5f),
        new Vector3(-707.5f, -914.3f, 19.2f),
        new Vector3(373.9f, 326.9f, 103.6f),
        new Vector3(1163.4f, -323.8f, 69.2f),
        new Vector3(-1820.5f, 792.5f, 138.1f),
        new Vector3(2557.5f, 382.3f, 108.6f),
        new Vector3(1961.1f, 3740.7f, 32.3f),
        new Vector3(1698.4f, 4924.4f, 42.1f),
        new Vector3(1729.2f, 6414.1f, 35.0f),
        new Vector3(-3243.0f, 1001.4f, 12.8f),
    };

    [DllImport("user32.dll")]
    static extern short GetAsyncKeyState(int vk);

    const string CFG = "scripts\\ItemSystem.cfg";

    bool[] prev = new bool[256];
    int mode;          // 0 closed, 1 bag, 2 shop
    bool sellMode;
    int catSel;        // 0..3
    int focus = 1;     // 0 = category list, 1 = item grid
    int sel;           // index in visible list
    int scrollRow;
    int qtyIdx;
    bool blipsMade;
    int boostEnd;
    int nextSave;
    bool iconsReady;
    GTA.UI.CustomSprite[] sprites = new GTA.UI.CustomSprite[7];
    List<int> vis = new List<int>();

    public ItemSystem()
    {
        Load();
        Tick += OnTick;
    }

    // ---------- Save / Load ----------
    void Save()
    {
        try
        {
            string s = "";
            for (int i = 0; i < Inv.Qty.Length; i++)
            {
                if (i > 0) s += ",";
                s += Inv.Qty[i];
            }
            File.WriteAllText(CFG, s);
        }
        catch (Exception) { }
    }

    void Load()
    {
        try
        {
            if (!File.Exists(CFG)) return;
            string[] a = File.ReadAllText(CFG).Trim().Split(',');
            for (int i = 0; i < Inv.Qty.Length && i < a.Length; i++)
            {
                int v = int.Parse(a[i]);
                Inv.Qty[i] = v < 0 ? 0 : v;
            }
        }
        catch (Exception) { }
    }

    // ---------- Helpers ----------
    bool Pressed(int vk)
    {
        bool d = (GetAsyncKeyState(vk) & 0x8000) != 0;
        bool r = d && !prev[vk];
        prev[vk] = d;
        return r;
    }

    static bool PadJustDis(int c)
    {
        return Function.Call<bool>(
            Hash.IS_DISABLED_CONTROL_JUST_PRESSED, 0, c);
    }

    static bool PadJust(int c)
    {
        return Function.Call<bool>(
            Hash.IS_CONTROL_JUST_PRESSED, 0, c);
    }

    static void Msg(string t)
    {
        GTA.UI.Screen.ShowSubtitle(t, 1800);
    }

    static void Rect(float cx, float cy, float w, float h,
        int r, int g, int b, int a)
    {
        Function.Call(Hash.DRAW_RECT, cx, cy, w, h, r, g, b, a);
    }

    // rectangle by top-left corner
    static void Box(float x, float y, float w, float h,
        int r, int g, int b, int a)
    {
        Rect(x + w / 2f, y + h / 2f, w, h, r, g, b, a);
    }

    // outline (t = thickness in screen height units)
    static void Frame(float x, float y, float w, float h, float t,
        int r, int g, int b, int a)
    {
        float tx = t * 0.5625f;
        Box(x, y, w, t, r, g, b, a);
        Box(x, y + h - t, w, t, r, g, b, a);
        Box(x, y, tx, h, r, g, b, a);
        Box(x + w - tx, y, tx, h, r, g, b, a);
    }

    static void DrawText(string s, float x, float y, float scale,
        int r, int g, int b, int a, bool center)
    {
        Function.Call(Hash.SET_TEXT_FONT, 0);
        Function.Call(Hash.SET_TEXT_SCALE, 0f, scale);
        Function.Call(Hash.SET_TEXT_COLOUR, r, g, b, a);
        Function.Call(Hash.SET_TEXT_CENTRE, center);
        Function.Call(Hash.SET_TEXT_DROP_SHADOW);
        Function.Call(Hash.BEGIN_TEXT_COMMAND_DISPLAY_TEXT, "STRING");
        Function.Call(
            Hash.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME, s);
        Function.Call(
            Hash.END_TEXT_COMMAND_DISPLAY_TEXT, x, y, 0);
    }

    static string Money(int v)
    {
        return v.ToString("N0");
    }

    static void PlayAnim(Ped p, string dict, string clip, int ms)
    {
        Function.Call(Hash.REQUEST_ANIM_DICT, dict);
        int tries = 0;
        while (!Function.Call<bool>(Hash.HAS_ANIM_DICT_LOADED, dict)
            && tries++ < 50)
            Script.Yield();
        if (!Function.Call<bool>(Hash.HAS_ANIM_DICT_LOADED, dict))
            return;
        Function.Call(Hash.TASK_PLAY_ANIM, p, dict, clip,
            8f, -8f, ms, 49, 0f, false, false, false);
    }

    void MakeBlips()
    {
        blipsMade = true;
        for (int i = 0; i < Shops.Length; i++)
        {
            Vector3 s = Shops[i];
            int b = Function.Call<int>(
                Hash.ADD_BLIP_FOR_COORD, s.X, s.Y, s.Z);
            Function.Call(Hash.SET_BLIP_SPRITE, b, 52);
            Function.Call(Hash.SET_BLIP_COLOUR, b, 2);
            Function.Call(Hash.SET_BLIP_AS_SHORT_RANGE, b, true);
            Function.Call(
                Hash.BEGIN_TEXT_COMMAND_SET_BLIP_NAME, "STRING");
            Function.Call(
                Hash.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME,
                "Item Shop");
            Function.Call(Hash.END_TEXT_COMMAND_SET_BLIP_NAME, b);
        }
    }

    // ---------- Icons ----------
    void EnsureIcons()
    {
        if (iconsReady) return;
        iconsReady = true;
        try
        {
            string dir = Path.GetFullPath("scripts\\ItemIcons");
            Directory.CreateDirectory(dir);
            for (int i = 0; i < IconFiles.Length; i++)
            {
                string path = Path.Combine(dir, IconFiles[i] + ".png");
                if (!File.Exists(path))
                    File.WriteAllBytes(path,
                        Convert.FromBase64String(IconB64[i]));
            }
        }
        catch (Exception) { }
    }

    // cx, cy = centre (0..1 of the screen), hN = height (0..1)
    void DrawIcon(int id, float cx, float cy, float hN)
    {
        try
        {
            float px = hN * 720f;
            float x = cx * 1280f - px / 2f;
            float y = cy * 720f - px / 2f;
            if (sprites[id] == null)
            {
                string path = Path.Combine(
                    Path.GetFullPath("scripts\\ItemIcons"),
                    IconFiles[id] + ".png");
                sprites[id] = new GTA.UI.CustomSprite(path,
                    new SizeF(px, px), new PointF(x, y));
            }
            GTA.UI.CustomSprite sp = sprites[id];
            sp.Size = new SizeF(px, px);
            sp.Position = new PointF(x, y);
            sp.Draw();
        }
        catch (Exception) { }
    }

    // ---------- Using items ----------
    void UseItem(Ped p, int id)
    {
        if (Inv.Qty[id] <= 0)
        {
            Msg("You don't have this item");
            return;
        }
        bool inVeh = p.IsInVehicle();

        if (id == Inv.Bandage)
        {
            Inv.WantBandage = true;
            mode = 0;
        }
        else if (id == Inv.Armor)
        {
            Inv.WantArmor = true;
            mode = 0;
        }
        else if (id == Inv.Medkit)
        {
            if (p.Health >= p.MaxHealth)
            {
                Msg("Health is full");
                return;
            }
            Inv.Take(id);
            p.Health = p.MaxHealth;
            Msg("Medkit used");
        }
        else if (id == Inv.Water)
        {
            Inv.Take(id);
            Function.Call(Hash.RESTORE_PLAYER_STAMINA,
                Game.Player.Handle, 1.0f);
            p.Health = Math.Min(p.MaxHealth, p.Health + 5);
            if (!inVeh)
                PlayAnim(p, "mp_player_intdrink", "loop_bottle", 1800);
            Msg("Water: stamina restored");
        }
        else if (id == Inv.Burger)
        {
            if (p.Health >= p.MaxHealth)
            {
                Msg("Health is full");
                return;
            }
            Inv.Take(id);
            p.Health = Math.Min(p.MaxHealth, p.Health + 25);
            if (!inVeh)
                PlayAnim(p, "mp_player_inteat@burger",
                    "mp_player_int_eat_burger", 2500);
            Msg("Burger: +25 health");
        }
        else if (id == Inv.Revive)
        {
            if (inVeh)
            {
                Msg("Get out of the vehicle to revive");
                return;
            }
            Inv.WantRevive = true;
            mode = 0;
        }
        else if (id == Inv.Energy)
        {
            Inv.Take(id);
            Function.Call(Hash.SET_RUN_SPRINT_MULTIPLIER_FOR_PLAYER,
                Game.Player.Handle, 1.3f);
            boostEnd = Game.GameTime + 30000;
            if (!inVeh)
                PlayAnim(p, "mp_player_intdrink", "loop_bottle", 1800);
            Msg("Energy Drink: speed boost 30s");
        }
    }

    // ---------- Shop ----------
    void BuyOrSell(int id)
    {
        Player pl = Game.Player;
        int q = QtyOptions[qtyIdx];
        if (!sellMode)
        {
            int total = BuyPrice[id] * q;
            if (pl.Money < total)
            {
                Msg("Not enough money");
                return;
            }
            pl.Money = pl.Money - total;
            Inv.Qty[id] += q;
            Inv.Dirty = true;
            Msg("Bought " + q + " x " + Names[id]);
        }
        else
        {
            if (Inv.Qty[id] <= 0)
            {
                Msg("You don't have this item");
                return;
            }
            if (q > Inv.Qty[id]) q = Inv.Qty[id];
            Inv.Qty[id] -= q;
            pl.Money = pl.Money + SellPrice[id] * q;
            Inv.Dirty = true;
            Msg("Sold " + q + " x " + Names[id]);
        }
    }

    // ---------- Visible list ----------
    void BuildVisible()
    {
        vis.Clear();
        for (int id = 0; id < Names.Length; id++)
        {
            if (catSel != 0 && Cat[id] != catSel) continue;
            bool needOwned = (mode == 1) || (mode == 2 && sellMode);
            if (needOwned && Inv.Qty[id] <= 0) continue;
            vis.Add(id);
        }
        if (sel >= vis.Count) sel = vis.Count - 1;
        if (sel < 0) sel = 0;
    }

    static List<int> OwnedAll()
    {
        List<int> l = new List<int>();
        for (int id = 0; id < Names.Length; id++)
            if (Inv.Qty[id] > 0) l.Add(id);
        return l;
    }

    // ---------- Drawing ----------
    const int COLS = 3;
    const int ROWS = 2;
    const float TW = 0.095f;
    const float TH = 0.215f;
    const float GAPX = 0.012f;
    const float GAPY = 0.014f;

    void DrawTile(int id, float tx, float ty, bool shop,
        bool selected, bool sellTile)
    {
        // glow + body + border
        if (selected)
            Box(tx - 0.003f, ty - 0.005f, TW + 0.006f, TH + 0.010f,
                255, 50, 170, 90);
        Box(tx, ty, TW, TH, 26, 12, 34, 245);
        if (selected)
            Frame(tx, ty, TW, TH, 0.004f, 255, 80, 190, 255);
        else
            Frame(tx, ty, TW, TH, 0.002f, 120, 40, 100, 255);

        float cx = tx + TW / 2f;

        if (!shop)
        {
            DrawIcon(id, cx, ty + 0.085f, 0.115f);
            DrawText("x" + Inv.Qty[id], tx + TW - 0.030f,
                ty + 0.105f, 0.34f, 255, 200, 235, 255, false);
            DrawText(Names[id], cx, ty + TH - 0.045f, 0.30f,
                255, 255, 255, 255, true);
        }
        else
        {
            DrawIcon(id, cx, ty + 0.062f, 0.090f);
            if (Inv.Qty[id] > 0)
                DrawText("x" + Inv.Qty[id], tx + TW - 0.028f,
                    ty + 0.008f, 0.28f, 255, 200, 235, 255, false);
            DrawText(Names[id], cx, ty + 0.112f, 0.28f,
                255, 255, 255, 255, true);

            int price = sellTile ? SellPrice[id] : BuyPrice[id];
            Box(tx + 0.017f, ty + 0.146f, 0.008f, 0.014f,
                255, 190, 40, 255);
            DrawText(Money(price), tx + 0.030f, ty + 0.142f, 0.32f,
                255, 255, 255, 255, false);

            float by = ty + TH - 0.040f;
            Box(tx + 0.008f, by, TW - 0.016f, 0.030f,
                selected ? 255 : 200, selected ? 60 : 40,
                selected ? 170 : 130, 255);
            DrawText(sellTile ? "SELL" : "BUY", cx, by + 0.003f, 0.32f,
                255, 255, 255, 255, true);
        }
    }

    void DrawPanel(float x0, bool interactive, bool shopPanel)
    {
        float y0 = 0.04f, w = 0.47f, h = 0.615f;

        // frame
        Box(x0 - 0.004f, y0 - 0.006f, w + 0.008f, h + 0.012f,
            255, 50, 170, 45);
        Box(x0, y0, w, h, 14, 7, 20, 240);
        Frame(x0, y0, w, h, 0.004f, 235, 60, 165, 255);

        // header
        Box(x0 + 0.014f, y0 + 0.014f, 0.045f, 0.082f,
            235, 60, 165, 255);
        DrawText(shopPanel ? "$" : "B", x0 + 0.0365f, y0 + 0.030f,
            0.85f, 20, 8, 24, 255, true);
        DrawText(shopPanel ? "SHOP" : "BAG", x0 + 0.072f, y0 + 0.010f,
            0.70f, 255, 255, 255, 255, false);
        DrawText(shopPanel ? "Choose items to buy" : "Check your items",
            x0 + 0.072f, y0 + 0.066f, 0.30f,
            235, 170, 215, 255, false);

        // right pill (items count / money)
        Box(x0 + w - 0.175f, y0 + 0.024f, 0.155f, 0.058f,
            38, 14, 48, 255);
        Frame(x0 + w - 0.175f, y0 + 0.024f, 0.155f, 0.058f, 0.002f,
            150, 45, 110, 255);
        if (shopPanel)
        {
            Box(x0 + w - 0.165f, y0 + 0.044f, 0.010f, 0.018f,
                255, 190, 40, 255);
            DrawText(Money(Game.Player.Money), x0 + w - 0.148f,
                y0 + 0.036f, 0.38f, 255, 255, 255, 255, false);
        }
        else
        {
            int total = 0;
            for (int i = 0; i < Inv.Qty.Length; i++) total += Inv.Qty[i];
            DrawText("ITEMS  " + total, x0 + w - 0.160f,
                y0 + 0.036f, 0.38f, 255, 255, 255, 255, false);
        }

        // categories
        int activeCat = interactive ? catSel : 0;
        for (int i = 0; i < CatNames.Length; i++)
        {
            float cy = y0 + 0.125f + i * 0.075f;
            bool on = (i == activeCat);
            if (on)
            {
                bool hot = interactive && focus == 0;
                Box(x0 + 0.012f, cy, 0.125f, 0.062f,
                    hot ? 255 : 190, hot ? 70 : 45, hot ? 180 : 130,
                    hot ? 255 : 235);
                Box(x0 + 0.012f, cy, 0.125f, 0.020f,
                    255, 130, 210, 70);
            }
            DrawText(CatNames[i], x0 + 0.074f, cy + 0.015f, 0.34f,
                255, on ? 255 : 215, on ? 255 : 235, 255, true);
        }

        if (shopPanel)
        {
            float my = y0 + 0.125f + CatNames.Length * 0.075f + 0.012f;
            DrawText(sellMode ? "MODE  SELL" : "MODE  BUY",
                x0 + 0.074f, my, 0.30f, 255, 130, 200, 255, true);
            DrawText("QTY  x" + QtyOptions[qtyIdx],
                x0 + 0.074f, my + 0.032f, 0.30f,
                235, 190, 225, 255, true);
        }

        // item list
        List<int> list;
        if (interactive) list = vis;
        else list = OwnedAll();

        float gx0 = x0 + 0.15f;
        float gy0 = y0 + 0.125f;

        int selRow = sel / COLS;
        if (interactive)
        {
            if (selRow < scrollRow) scrollRow = selRow;
            if (selRow >= scrollRow + ROWS) scrollRow = selRow - ROWS + 1;
            if (scrollRow < 0) scrollRow = 0;
        }
        int sr = interactive ? scrollRow : 0;

        if (list.Count == 0)
        {
            DrawText(shopPanel ? "Nothing to show" : "Your bag is empty",
                gx0 + 0.155f, gy0 + 0.18f, 0.42f,
                200, 160, 190, 255, true);
        }

        int start = sr * COLS;
        int end = Math.Min(list.Count, start + COLS * ROWS);
        for (int i = start; i < end; i++)
        {
            int rr = (i - start) / COLS;
            int cc = (i - start) % COLS;
            float tx = gx0 + cc * (TW + GAPX);
            float ty = gy0 + rr * (TH + GAPY);
            bool selected = interactive && focus == 1 && i == sel;
            DrawTile(list[i], tx, ty, shopPanel, selected,
                shopPanel && sellMode);
        }

        // footer hint
        Box(x0 + 0.012f, y0 + h - 0.046f, w - 0.024f, 0.034f,
            34, 12, 44, 255);
        string hint;
        if (!interactive) hint = "Your items";
        else if (shopPanel)
            hint = "ENTER buy   T mode   Q qty   BACK close";
        else
            hint = "ENTER use   LEFT categories   BACK close";
        DrawText(hint, x0 + 0.02f, y0 + h - 0.040f, 0.28f,
            235, 180, 220, 255, false);
    }

    void DrawUi()
    {
        EnsureIcons();
        BuildVisible();
        if (mode == 1)
        {
            DrawPanel(0.02f, true, false);
        }
        else
        {
            DrawPanel(0.02f, false, false);
            DrawPanel(0.51f, true, true);
        }
    }

    // ---------- Main loop ----------
    void OnTick(object sender, EventArgs e)
    {
        try { Tick2(); }
        catch (Exception) { }
    }

    void OpenMenu(int m)
    {
        mode = m;
        sel = 0;
        scrollRow = 0;
        catSel = 0;
        focus = 1;
        sellMode = false;
        qtyIdx = 0;
    }

    void Tick2()
    {
        Ped p = Game.Player.Character;

        bool kBag = Pressed(BagKey);
        bool kShop = Pressed(ShopKey);
        bool kAny = Pressed(AnywhereKey);
        bool kUp = Pressed(KUp);
        bool kDown = Pressed(KDown);
        bool kLeft = Pressed(KLeft);
        bool kRight = Pressed(KRight);
        bool kEnter = Pressed(KEnter);
        bool kBack = Pressed(KBack);
        bool kTab = Pressed(KTab);
        bool kBS = Pressed(KBuySell);
        bool kQty = Pressed(KQty);

        if (p == null || !p.Exists() || p.IsDead)
        {
            mode = 0;
            return;
        }

        int now = Game.GameTime;

        if (!blipsMade) MakeBlips();

        // energy drink ends
        if (boostEnd != 0 && now > boostEnd)
        {
            boostEnd = 0;
            Function.Call(Hash.SET_RUN_SPRINT_MULTIPLIER_FOR_PLAYER,
                Game.Player.Handle, 1.0f);
        }

        // save when something changed
        if (Inv.Dirty && now >= nextSave)
        {
            nextSave = now + 500;
            Inv.Dirty = false;
            Save();
        }

        // ---------- shops in the world ----------
        if (mode == 0 && !p.IsInVehicle())
        {
            Vector3 pos = p.Position;
            for (int i = 0; i < Shops.Length; i++)
            {
                Vector3 s = Shops[i];
                float dx = pos.X - s.X;
                float dy = pos.Y - s.Y;
                float d2 = dx * dx + dy * dy;
                if (d2 > 900f) continue;     // 30 m

                Function.Call(Hash.DRAW_MARKER, 1,
                    s.X, s.Y, s.Z - 1.0f,
                    0f, 0f, 0f, 0f, 0f, 0f,
                    1.2f, 1.2f, 0.6f,
                    255, 60, 170, 120,
                    false, false, 2, false, 0, 0, false);

                float dz = Math.Abs(pos.Z - s.Z);
                if (d2 < 4f && dz < 3f)
                {
                    DrawText("Press E - Item Shop",
                        0.5f, 0.88f, 0.5f, 255, 255, 255, 255, true);
                    if (kShop || PadJust(51)) OpenMenu(2);
                }
            }

            if (ShopAnywhere && kAny) OpenMenu(2);
        }

        // ---------- bag key ----------
        if (kBag)
        {
            if (mode != 0) mode = 0;
            else OpenMenu(1);
        }

        // ---------- menu ----------
        if (mode == 0) return;

        Function.Call(Hash.DISABLE_ALL_CONTROL_ACTIONS, 0);

        bool up = kUp || PadJustDis(172);
        bool down = kDown || PadJustDis(173);
        bool left = kLeft || PadJustDis(174);
        bool right = kRight || PadJustDis(175);
        bool enter = kEnter || PadJustDis(201);
        bool back = kBack || PadJustDis(202);
        bool tab = kTab || PadJustDis(206);
        bool buySell = kBS || PadJustDis(204);
        bool qty = kQty || PadJustDis(203);

        BuildVisible();
        bool enterUse = enter;
        if (focus == 0)
        {
            // category list: Up/Down changes category
            int nc = CatNames.Length;
            if (up)
            {
                catSel = (catSel + nc - 1) % nc;
                sel = 0;
                scrollRow = 0;
            }
            if (down)
            {
                catSel = (catSel + 1) % nc;
                sel = 0;
                scrollRow = 0;
            }
            if (right || enter)
            {
                focus = 1;
                enterUse = false;
            }
        }
        else
        {
            // item grid: Left on the first column goes to categories
            if (up && sel - COLS >= 0) sel -= COLS;
            if (down && sel + COLS < vis.Count) sel += COLS;
            if (left)
            {
                if (sel % COLS == 0) focus = 0;
                else sel--;
            }
            if (right && sel + 1 < vis.Count) sel++;
        }

        if (tab)
        {
            catSel = (catSel + 1) % CatNames.Length;
            sel = 0;
            scrollRow = 0;
        }
        if (mode == 2 && buySell)
        {
            sellMode = !sellMode;
            sel = 0;
            scrollRow = 0;
        }
        if (mode == 2 && qty)
            qtyIdx = (qtyIdx + 1) % QtyOptions.Length;

        if (back) mode = 0;

        if (enterUse && focus == 1 && mode != 0)
        {
            BuildVisible();
            if (vis.Count > 0)
            {
                int id = vis[sel];
                if (mode == 1) UseItem(p, id);
                else BuyOrSell(id);
            }
        }

        if (mode != 0) DrawUi();
    }
}
